// Sri Lanka map data — provinces and districts share ONE coordinate
// system (viewBox 0 0 1000 1000). Province paths are the exact polygon
// union of their child districts (with sliver-artifact cleanup), so
// hover/highlight lines up pixel-for-pixel between the two layers.
//
// ids match the Prisma seed exactly:
//   province.id  1=Northern 2=Eastern 3=North Central 4=North Western
//                5=Central 6=Uva 7=Sabaragamuwa 8=Western 9=Southern
//   district.id  1..25 in seed insertion order (Jaffna=1 ... Matara=25)

export interface BBox {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface HistoricalPlace {
  id: number;
  name: string;
  category: string;
  description: string;
  image: string | null;
  latitude: number;
  longitude: number;
  /** 0-100, position of the pin within the district's bounding box */
  anchorXPct: number;
  anchorYPct: number;
  districtId: number;
}

export interface District {
  id: number;
  name: string;
  province: string;
  provinceId: number;
  color: string;
  path: string;
  bbox: BBox;
  labelX: number;
  labelY: number;
  historicalPlaces: HistoricalPlace[];
}

export interface Province {
  id: number;
  name: string;
  regionCode: string;
  path: string;
  bbox: BBox;
  labelX: number;
  labelY: number;
  districts: District[];
}

export const VIEWBOX = "0 0 1000 1000";

